<script setup lang="ts">
import {computed,onBeforeUnmount,ref,watch} from 'vue'
import {request} from '@/api/client'
const period=ref(30),data=ref<{days:{date:string;answers:number;correct:number}[];weakPoints:{term:string;kind:string;detail:string;correct:number;wrong:number;independent:number}[];answers:number;correct:number}>(),error=ref(''),loading=ref(false);let active=true,epoch=0
const max=computed(()=>Math.max(1,...(data.value?.days.map(d=>d.answers)||[])))
const names:Record<string,string>={MEANING:'释义',SPELLING:'拼写',COLLOCATION:'搭配',LISTENING:'听写'}
onBeforeUnmount(()=>{active=false;epoch++})
watch(period,async()=>{const v=++epoch;loading.value=true;error.value='';try{const r=await request<typeof data.value>(`/vocabulary/statistics?days=${period.value}`);if(active&&v===epoch)data.value=r}catch(e){if(active&&v===epoch)error.value=(e as Error).message}finally{if(active&&v===epoch)loading.value=false}},{immediate:true})
</script>
<template><section class="vocabulary-statistics"><header><h3>学习趋势与薄弱项</h3><select v-model="period" class="field-input" aria-label="统计范围"><option :value="7">近 7 天</option><option :value="30">近 30 天</option><option :value="90">近 90 天</option></select></header><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="loading" role="status">正在整理学习记录…</p><template v-if="data"><p>{{data.answers}} 次作答 · 正确率 {{data.answers?Math.round(data.correct/data.answers*100):0}}%。没有记录的日期显示为零；即时、提示和独立回忆仍分开记录。</p><div class="trend" aria-label="每天的答题次数"><div v-for="d in data.days" :key="d.date" :title="`${d.date}：${d.answers} 题，${d.correct} 正确`"><i :style="{height:`${Math.max(2,d.answers/max*100)}%`}" /></div></div><p>{{data.days[0]?.date}} — {{data.days.at(-1)?.date}}</p><h4>需要继续练习</h4><p v-if="!data.weakPoints.length">尚无分项错题记录。</p><div v-for="(s,i) in data.weakPoints" :key="i" class="weak-row"><strong>{{s.term}}</strong><span>{{names[s.kind]||s.kind}}</span><span>{{s.detail}}</span><small>错 {{s.wrong}} · 对 {{s.correct}} · 独立 {{s.independent}}</small></div></template></section></template>
<style scoped>.vocabulary-statistics{border-top:1px solid var(--line);padding:24px 0}header{display:flex;justify-content:space-between;align-items:center}select{width:150px}.trend{display:flex;gap:4px;height:130px;border-bottom:1px solid var(--line);margin-top:30px}.trend>div{flex:1;display:flex;align-items:flex-end}.trend i{width:100%;background:var(--green);opacity:.6;border-radius:2px 2px 0 0}.weak-row{display:grid;grid-template-columns:140px 70px 1fr 160px;gap:16px;padding:12px 0;border-bottom:1px solid var(--line);font-size:13px}.weak-row small,p{color:var(--muted);font-size:12px}</style>
